export async function callTool(name, args) {
  if (name !== 'ticket_create') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate title
  if (typeof args.title !== 'string' || args.title.trim() === '') {
    throw new Error('title is required and must be non-empty');
  }

  // Validate description
  if (typeof args.description !== 'string' || args.description.trim() === '') {
    throw new Error('description is required and must be non-empty');
  }

  // Validate priority if present
  if (args.priority !== undefined) {
    const valid = ['low', 'normal', 'high'];
    if (!valid.includes(args.priority)) {
      throw new Error(`priority must be one of: ${valid.join(', ')}`);
    }
  }

  // Check for extra fields
  const allowed = ['title', 'description', 'priority'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  const ticketId = `t${nextId++}`;
  const priority = args.priority || 'normal';

  return {
    content: [
      {
        type: 'text',
        text: `Ticket ${ticketId} created with priority ${priority}.`,
      },
    ],
  };
}
